import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { getCart, removeFromCart } from '../../services/cartService';
import './CartPage.css';

const CartPage = () => {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadCart();
  }, []);

  const loadCart = async () => {
    try {
      const data = await getCart();
      setItems(data);
    } catch (e) {
      console.error('Ошибка загрузки корзины', e);
    } finally {
      setLoading(false);
    }
  };

  const handleRemove = async (id) => {
    await removeFromCart(id);
    setItems(prev => prev.filter(i => i.id !== id));
  };

  const totalPrice = items.reduce(
    (sum, item) => sum + item.quantity * item.tour.price,
    0
  );

  if (loading) return <div>Загрузка...</div>;

  return (
    <div className="cart-page">
      <div className="cart-container">
        <h1 className="cart-title">Корзина</h1>

        {items.length === 0 ? (
          <div className="cart-empty">
            <h2>Корзина пуста</h2>
            <Link to="/catalog">Перейти в каталог</Link>
          </div>
        ) : (
          <>
            <div className="cart-list">
              {items.map(item => (
                <div key={item.id} className="cart-item">
                  <img
                    src={`https://localhost:5066/images/tours/${item.tour.imageFileName}`}
                    alt={item.tour.title}
                  />

                  <div>
                    <h3>{item.tour.title}</h3>
                    <p>{item.tour.city?.country?.name}, {item.tour.city?.name}</p>
                    <p>Кол-во: {item.quantity}</p>

                    <button onClick={() => handleRemove(item.id)}>
                      Удалить
                    </button>
                  </div>

                  <div>
                    {(item.quantity * item.tour.price).toLocaleString()} ₽
                  </div>
                </div>
              ))}
            </div>

            <div className="cart-summary">
              Итого: <strong>{totalPrice.toLocaleString()} ₽</strong>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default CartPage;
